<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api'
import SalesOrderPrint from '../components/SalesOrderPrint.vue'

const rows=ref<any[]>([]),loading=ref(false),editor=ref(false),detail=ref<any>(null),resolving=ref(false),availableOrders=ref<any[]>([]),orderSearching=ref(false),orderTail=ref('')
const orderTailInput=ref<any>(null)
const newDraft=ref(false),draftDirty=ref(false)
const inlineDispatch=ref<any>(null),inlineDispatchLoading=ref(false),selectedDispatchId=ref<number|null>(null)
const salesDetailDialog=ref(false),salesDetailLoading=ref(false),salesDetail=ref<any>(null)
const dispatchPrintDialog=ref(false)
const headerDialog=ref(false),headerSaving=ref(false),referenceDialog=ref(false),referenceSaving=ref(false),referenceType=ref<'route'|'vehicle'|'employee'>('route')
const routes=ref<any[]>([]),vehicles=ref<any[]>([]),employees=ref<any[]>([])
import { localToday } from '../utils/date'
const today=localToday()
const query=reactive({keyword:'',status:'',dateFrom:today,dateTo:today,recorder:'',sortBy:'date',sortDirection:'asc',page:1,pageSize:100})
const headerForm=reactive({dispatchDate:'',routeId:null as number|null,vehicleId:null as number|null,driverId:null as number|null,deliveryPersonId:null as number|null,remark:'',version:0})
const referenceForm=reactive({code:'',name:'',plateNo:'',phone:''})
const totalAmount=computed(()=>detail.value?.orders?.reduce((sum:number,item:any)=>sum+Number(item.amount||0),0)||0)
const drivers=computed(()=>employees.value.filter((item:any)=>`${item.typeName||''} ${item.positionName||''}`.includes('司机')))
const referenceTitle=computed(()=>referenceType.value==='route'?'新增路线':referenceType.value==='vehicle'?'新增车辆':'新增员工')
function vehicleLabel(item:any){const code=String(item.code||'').trim(),plate=String(item.plateNo||'').trim();return !plate||plate.toLowerCase()===code.toLowerCase()?code:`${code} · ${plate}`}
function employeeLabel(item:any){const code=String(item.code||'').trim(),name=String(item.name||'').trim();const clean=name.endsWith(code)?name.slice(0,-code.length).trim():name;return clean?`${code} ${clean}`:code}
function formatDateTime(value:any){return value?String(value).replace('T',' ').slice(0,19):'—'}
async function focusOrderEntry(){await nextTick();orderTailInput.value?.focus()}

async function load(){loading.value=true;try{const{data}=await api.get('/dispatch-sheets',{params:query});rows.value=data.data.items}finally{loading.value=false}}
function handleSortChange({prop,order}:{prop:string,order:string}){query.sortBy=prop==='dispatchNo'?'documentNo':'date';query.sortDirection=order==='descending'?'desc':'asc';query.page=1;load()}
async function focusNewDispatch(dispatchNo:string){await nextTick();const row=Array.from(document.querySelectorAll('.el-table__body-wrapper tbody tr')).find(x=>x.textContent?.includes(dispatchNo));if(!row)return;row.classList.add('newly-created-row');row.scrollIntoView({behavior:'smooth',block:'center'});window.setTimeout(()=>row.classList.remove('newly-created-row'),5000)}
function resetQuery(){Object.assign(query,{keyword:'',status:'',dateFrom:'',dateTo:'',recorder:'',sortBy:'date',sortDirection:'asc',page:1});load()}
async function loadOptions(){const [r,v,e]=await Promise.all([api.get('/routes'),api.get('/vehicles'),api.get('/reference-data/employees',{params:{enabled:true,page:1,pageSize:100}})]);routes.value=r.data.data;vehicles.value=v.data.data;employees.value=e.data.data.items}
function resetHeader(){Object.assign(headerForm,{dispatchDate:localToday(),routeId:null,vehicleId:null,driverId:null,deliveryPersonId:null,remark:'',version:0})}
async function openNew(){resetHeader();await loadOptions();detail.value={id:null,dispatchNo:'新建',dispatchDate:headerForm.dispatchDate,routeId:null,routeName:'',vehicleId:null,vehicleCode:'',driverId:null,driverName:'',deliveryPersonId:null,deliveryPersonName:'',status:'DRAFT',remark:'',version:0,orders:[],createdByName:'',createdAt:null,updatedByName:'',updatedAt:null,approvedByName:'',approvedAt:null,printedByName:'',printedAt:null,printCount:0};newDraft.value=true;draftDirty.value=false;availableOrders.value=[];orderTail.value='';editor.value=true;await nextTick();orderTailInput.value?.focus()}
async function ensureDraft(){if(detail.value?.id)return;const{data}=await api.post('/dispatch-sheets',headerForm);detail.value=data.data;syncHeaderForm();newDraft.value=true;draftDirty.value=true;await load();await focusNewDispatch(data.data.dispatchNo)}
async function openHeaderEdit(){await loadOptions();Object.assign(headerForm,{dispatchDate:detail.value.dispatchDate,routeId:detail.value.routeId,vehicleId:detail.value.vehicleId,driverId:detail.value.driverId,deliveryPersonId:detail.value.deliveryPersonId,remark:detail.value.remark,version:detail.value.version});headerDialog.value=true}
async function saveHeader(showMessage=true){if(!headerForm.dispatchDate)return ElMessage.warning('请选择日期');headerSaving.value=true;try{if(!detail.value.id){await ensureDraft()}else{await api.put(`/dispatch-sheets/${detail.value.id}`,headerForm);await refreshDetail()}headerDialog.value=false;newDraft.value=false;draftDirty.value=false;if(showMessage)ElMessage.success('出车表草稿已保存')}finally{headerSaving.value=false}}
function syncHeaderForm(){if(!detail.value)return;Object.assign(headerForm,{dispatchDate:detail.value.dispatchDate,routeId:detail.value.routeId,vehicleId:detail.value.vehicleId,driverId:detail.value.driverId,deliveryPersonId:detail.value.deliveryPersonId,remark:detail.value.remark||'',version:detail.value.version})}
async function openDetail(row:any){const[{data}]=await Promise.all([api.get(`/dispatch-sheets/${row.id}`),loadOptions()]);detail.value=data.data;syncHeaderForm();newDraft.value=false;draftDirty.value=false;editor.value=true;availableOrders.value=[];orderTail.value=''}
async function selectDispatch(row:any){selectedDispatchId.value=row.id;inlineDispatchLoading.value=true;try{const{data}=await api.get(`/dispatch-sheets/${row.id}`);if(selectedDispatchId.value===row.id)inlineDispatch.value=data.data}finally{if(selectedDispatchId.value===row.id)inlineDispatchLoading.value=false}}
async function openInlineDispatchDetail(){if(inlineDispatch.value)await openDetail({id:inlineDispatch.value.id})}
async function approveFromList(row:any){
  if(row.status!=='DRAFT')return
  if(!row.dispatchDate)return ElMessage.warning('审核前必须填写日期')
  await ElMessageBox.confirm(`确认审核出车表 ${row.dispatchNo}？审核后不能继续修改。`,'审核确认',{type:'warning'})
  await api.post(`/dispatch-sheets/${row.id}/approve`,{version:row.version})
  await load()
  if(selectedDispatchId.value===row.id)await selectDispatch(row)
  ElMessage.success('出车表审核成功')
}
async function refreshDetail(preserveHeader=false){const{data}=await api.get(`/dispatch-sheets/${detail.value.id}`);detail.value=data.data;if(preserveHeader)headerForm.version=detail.value.version;else syncHeaderForm();await load()}
function errorMessage(error:any){
  const body=error.response?.data
  const message=body?.message||body?.detail||body?.data?.message||body?.data?.detail||body?.error
  if(message)return message
  if(!error.response)return '无法连接服务器，请检查服务是否正在运行'
  return '操作未完成，请刷新页面后重试'
}
async function addResolvedOrder(orderNo:string){resolving.value=true;try{await ensureDraft();await api.post(`/dispatch-sheets/${detail.value.id}/orders`,{orderNo});await refreshDetail(true);draftDirty.value=true;availableOrders.value=[];orderTail.value='';await nextTick();orderTailInput.value?.focus();ElMessage.success(`销售单 ${orderNo} 已加入出车表`)}catch(error:any){ElMessage.error(errorMessage(error))}finally{resolving.value=false}}
function numericTail(orderNo:string){const match=String(orderNo||'').match(/(\d+)$/);return match?String(Number(match[1])):''}
async function resolveOrderTail(){const tail=orderTail.value.trim();if(tail&&!/^\d+$/.test(tail))return ElMessage.warning('请输入销售单末尾的数字，例如 3、03 或 003');orderSearching.value=true;try{await ensureDraft();let matches:any[]=[];if(tail){try{const{data}=await api.get(`/dispatch-sheets/${detail.value.id}/order-tail-candidates`,{params:{tail}});matches=data.data}catch{}if(!matches.length){const{data}=await api.get(`/dispatch-sheets/${detail.value.id}/available-orders`);const normalized=String(Number(tail));matches=data.data.filter((item:any)=>numericTail(item.orderNo)===normalized)}}else{const{data}=await api.get(`/dispatch-sheets/${detail.value.id}/available-orders`);matches=data.data}availableOrders.value=matches;if(tail&&matches.length===1)return await addResolvedOrder(matches[0].orderNo);if(matches.length===0)return ElMessage.warning(tail?`没有找到尾号 ${tail} 的可加入销售单，请确认该销售单已打印且未加入其他出车表`:'没有可加入的已打印销售单');if(tail)ElMessage.info(`找到 ${matches.length} 张销售单，请选择正确单据`)}catch(error:any){ElMessage.error(errorMessage(error))}finally{orderSearching.value=false}}
function markDraftDirty(){draftDirty.value=true}
async function discardNewDraft(){if(detail.value?.id)await api.delete(`/dispatch-sheets/${detail.value.id}/draft`);detail.value=null;newDraft.value=false;draftDirty.value=false;editor.value=false;await load()}
function finishClose(done?:()=>void){detail.value=null;editor.value=false;if(done)done()}
async function closeEditor(done?:()=>void){if(detail.value?.status!=='DRAFT'){finishClose(done);return}if(newDraft.value&&!draftDirty.value){finishClose(done);return}if(newDraft.value){try{await ElMessageBox.confirm('是否保存对当前出车表的修改？','资料保存',{confirmButtonText:'保存',cancelButtonText:'不保存',distinguishCancelAndClose:true,type:'warning'});await saveHeader(false);finishClose(done)}catch(action:any){if(action==='cancel'){try{await discardNewDraft();if(done)done()}catch(error:any){ElMessage.error(errorMessage(error))}}return}return}if(draftDirty.value){syncHeaderForm();draftDirty.value=false}finishClose(done)}
async function removeOrder(row:any){try{await api.delete(`/dispatch-sheets/${detail.value.id}/orders/${row.linkId}`);await refreshDetail(true);draftDirty.value=true;ElMessage.success('已移除销售单，可重新输入尾号加入')}catch(error:any){ElMessage.error(errorMessage(error))}}
async function openSalesDetail(row:any){salesDetailLoading.value=true;salesDetailDialog.value=true;try{const{data}=await api.get(`/sales-orders/${row.salesOrderId}`);salesDetail.value=data.data}finally{salesDetailLoading.value=false}}
async function printRelated(){await nextTick();window.print()}
function openDispatchPrint(){dispatchPrintDialog.value=true}
async function printDispatchSheet(){if(detail.value?.status!=='APPROVED')return ElMessage.warning('请先由主管审核出车表，再进行打印');window.print();try{await ElMessageBox.confirm('出车表是否已经成功打印或另存为 PDF？','确认出车表打印结果',{type:'warning',confirmButtonText:'打印成功',cancelButtonText:'打印失败或取消'});const{data}=await api.post(`/dispatch-sheets/${detail.value.id}/confirm-print`,{version:detail.value.version});ElMessage.success(data.data.firstPrint?'出车表已标记为已打印':'出车表补打次数已更新');await refreshDetail();dispatchPrintDialog.value=true}catch(e:any){if(e==='cancel'||e==='close')return;ElMessage.error(errorMessage(e))}}
function csvCell(value:any){return `"${String(value??'').replaceAll('"','""')}"`}
function exportDispatch(){if(!detail.value)return;const lines=[['序号','单据类型','开单日期','销售单号','客户编号','客户名称','业务员','结算方式','金额','备注'],...detail.value.orders.map((x:any)=>[x.sequenceNo,'送货单',x.orderDate,x.orderNo,x.customerCode,x.customerName,x.salespersonName,x.settlementMethod,x.amount,x.remark||''])];const blob=new Blob(['\ufeff'+lines.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${detail.value.dispatchNo}-出车表.csv`;a.click();URL.revokeObjectURL(url)}
async function approve(){if(!detail.value?.id)return ElMessage.warning('审核失败，请先保存');if(draftDirty.value)await saveHeader(false);if(!detail.value.dispatchDate)return ElMessage.warning('审核前必须填写日期');await ElMessageBox.confirm(`确认审核出车表 ${detail.value.dispatchNo}？审核后不能继续修改。`,'审核确认',{type:'warning'});await api.post(`/dispatch-sheets/${detail.value.id}/approve`,{version:detail.value.version});await refreshDetail();ElMessage.success('出车表审核成功')}
async function voidSheet(row:any){const target=detail.value?.id===row.id?detail.value:row;if(target.status!=='DRAFT')return ElMessage.warning('已审核的出车表不能更改');const{value}=await ElMessageBox.prompt('请输入作废原因','作废出车表',{inputValidator:v=>!!v||'必须填写原因',type:'warning'});await api.post(`/dispatch-sheets/${target.id}/void`,{version:target.version,reason:value});if(detail.value?.id===target.id)await refreshDetail();await load();ElMessage.success('出车表已作废')}
function openReference(type:'route'|'vehicle'|'employee'){referenceType.value=type;Object.assign(referenceForm,{code:'',name:'',plateNo:'',phone:''});referenceDialog.value=true}
async function saveReference(){if(!referenceForm.code.trim())return ElMessage.warning('请填写编号');if(referenceType.value!=='vehicle'&&!referenceForm.name.trim())return ElMessage.warning('请填写名称');referenceSaving.value=true;try{const path=referenceType.value==='route'?'/routes':referenceType.value==='vehicle'?'/vehicles':'/employees';const{data}=await api.post(path,referenceForm);await loadOptions();if(referenceType.value==='route')headerForm.routeId=data.data.id;else if(referenceType.value==='vehicle')headerForm.vehicleId=data.data.id;else headerForm.driverId=data.data.id;referenceDialog.value=false;ElMessage.success(`${referenceTitle.value}成功`)}finally{referenceSaving.value=false}}
function statusText(status:string){return({DRAFT:'草稿',APPROVED:'已审核',VOIDED:'已作废',COMPLETED:'历史已完成',REVERSED:'历史已撤销'} as any)[status]||status}
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>出车表</h1><p>编入已打印送货单的销售单，由主管审核出车表</p></div><el-button type="primary" @click="openNew">新建出车表</el-button></div>
    <el-card class="dispatch-split-card"><div class="dispatch-search"><div class="dispatch-search-row"><el-date-picker v-model="query.dateFrom" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><span>至</span><el-date-picker v-model="query.dateTo" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-input v-model="query.keyword" clearable placeholder="出车表号 / 路线 / 车辆 / 司机 / 送货人" @keyup.enter="load"/><el-input v-model="query.recorder" clearable placeholder="录入人" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button><el-button @click="resetQuery">清空条件</el-button></div><el-radio-group v-model="query.status" @change="load"><el-radio-button value="">全部</el-radio-button><el-radio-button value="DRAFT">草稿</el-radio-button><el-radio-button value="APPROVED">已审核</el-radio-button><el-radio-button value="VOIDED">已作废</el-radio-button></el-radio-group></div>
      <el-table :data="rows" v-loading="loading" height="42vh" stripe highlight-current-row :default-sort="{prop:'dispatchDate',order:'ascending'}" @sort-change="handleSortChange" @row-click="selectDispatch" @row-dblclick="openDetail"><el-table-column prop="dispatchNo" label="出车表号" width="155" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column prop="dispatchDate" label="日期" width="115" sortable="custom" :sort-orders="['ascending','descending']"/><el-table-column prop="routeName" label="路线"/><el-table-column prop="vehicleCode" label="车辆"/><el-table-column prop="driverName" label="司机"/><el-table-column prop="deliveryPersonName" label="送货人"/><el-table-column prop="orderCount" label="单据数" width="85"/><el-table-column prop="totalAmount" label="总金额" width="120"/><el-table-column label="状态" width="110"><template #default="scope"><el-tag :type="scope.row.status==='APPROVED'?'success':scope.row.status==='COMPLETED'?'primary':scope.row.status==='REVERSED'?'warning':scope.row.status==='VOIDED'?'danger':'info'">{{statusText(scope.row.status)}}</el-tag></template></el-table-column><el-table-column label="打印状态" width="120"><template #default="scope"><el-tag :type="scope.row.printedAt?'warning':'info'">{{scope.row.printedAt?`已打印 × ${scope.row.printCount||1}`:'未打印'}}</el-tag></template></el-table-column><el-table-column label="操作" width="205" fixed="right"><template #default="scope"><el-button link type="primary" @click.stop="openDetail(scope.row)">详情</el-button><el-button v-if="scope.row.status==='DRAFT'" link type="success" @click.stop="approveFromList(scope.row)">审核</el-button><el-button v-if="scope.row.status==='DRAFT'" link type="danger" @click.stop="voidSheet(scope.row)">作废</el-button></template></el-table-column></el-table>
      <div class="inline-detail-panel" v-loading="inlineDispatchLoading"><div class="inline-detail-heading"><div><strong>{{inlineDispatch?`出车表 ${inlineDispatch.dispatchNo} 的销售单`:'单击上方出车表查看销售单'}}</strong><span v-if="inlineDispatch">下方详情可独立滚动；双击销售单可打开完整出车表</span></div><span v-if="inlineDispatch">共 {{inlineDispatch.orders?.length||0}} 张，合计 ¥{{Number(inlineDispatch.totalAmount||0).toFixed(2)}}</span></div><el-table v-if="inlineDispatch" :data="inlineDispatch.orders" border highlight-current-row height="190" @row-dblclick="openInlineDispatchDetail"><el-table-column prop="sequenceNo" label="序号" width="65"/><el-table-column prop="orderNo" label="销售单号" width="150"/><el-table-column prop="orderDate" label="开单日期" width="110"/><el-table-column prop="customerCode" label="客户编号" width="105"/><el-table-column prop="customerName" label="客户名称" min-width="190"/><el-table-column prop="salespersonName" label="业务员" width="100"/><el-table-column prop="settlementMethod" label="结算方式" width="100"/><el-table-column prop="amount" label="金额" width="110"/></el-table><el-empty v-else :image-size="54" description="请单击一张出车表"/></div>
    </el-card>

    <el-dialog v-model="headerDialog" title="编辑出车表表头" width="720px">
      <el-form label-width="90px"><el-form-item label="日期" required><el-date-picker v-model="headerForm.dispatchDate" type="date" value-format="YYYY-MM-DD" :clearable="false"/></el-form-item>
        <el-form-item label="路线"><div class="reference-row"><el-select v-model="headerForm.routeId" filterable clearable placeholder="可留空"><el-option v-for="item in routes" :key="item.id" :label="`${item.code} ${item.name}`" :value="item.id"/></el-select><el-button @click="openReference('route')">新增路线</el-button></div></el-form-item>
        <el-form-item label="车辆"><div class="reference-row"><el-select v-model="headerForm.vehicleId" filterable clearable placeholder="可留空"><el-option v-for="item in vehicles" :key="item.id" :label="vehicleLabel(item)" :value="item.id"/></el-select><el-button @click="openReference('vehicle')">新增车辆</el-button></div></el-form-item>
        <el-form-item label="司机"><div class="reference-row"><el-select v-model="headerForm.driverId" filterable clearable placeholder="可留空"><el-option v-for="item in drivers" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select><el-button @click="openReference('employee')">新增员工</el-button></div></el-form-item>
        <el-form-item label="送货人"><el-select v-model="headerForm.deliveryPersonId" filterable clearable placeholder="可选"><el-option v-for="item in employees" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="headerForm.remark" type="textarea"/></el-form-item></el-form>
      <template #footer><el-button @click="headerDialog=false">取消</el-button><el-button type="primary" :loading="headerSaving" @click="saveHeader">保存</el-button></template>
    </el-dialog>

    <el-dialog v-model="referenceDialog" :title="referenceTitle" width="500px" append-to-body><el-form label-width="90px"><el-form-item label="编号" required><el-input v-model="referenceForm.code"/></el-form-item><el-form-item v-if="referenceType!=='vehicle'" label="名称" required><el-input v-model="referenceForm.name"/></el-form-item><el-form-item v-if="referenceType==='vehicle'" label="车牌"><el-input v-model="referenceForm.plateNo"/></el-form-item><el-form-item v-if="referenceType==='employee'" label="电话"><el-input v-model="referenceForm.phone"/></el-form-item></el-form><template #footer><el-button @click="referenceDialog=false">取消</el-button><el-button type="primary" :loading="referenceSaving" @click="saveReference">保存</el-button></template></el-dialog>

    <el-dialog v-model="editor" width="1180px" top="3vh" :show-close="true" :before-close="closeEditor" class="dispatch-document-dialog">
      <template #header>
        <div class="document-toolbar">
          <el-button :disabled="!detail?.id" @click="openDispatchPrint">打印预览</el-button>
          <el-button v-if="detail?.status==='DRAFT'" type="primary" :loading="headerSaving" @click="saveHeader()">保存</el-button>
          <el-button @click="closeEditor()">取消</el-button>
          <el-button v-if="detail?.status==='DRAFT'" type="danger" plain :disabled="!detail?.id" @click="voidSheet(detail)">作废</el-button>
          <el-button v-if="detail?.status==='DRAFT'" @click="focusOrderEntry">增加销售单</el-button>
          <el-button v-if="detail?.status==='DRAFT'" type="success" @click="approve">审核</el-button>
        </div>
      </template>
      <template v-if="detail">
        <div class="legacy-document">
          <div class="document-heading">
            <div class="document-title"><h2>出 车 表</h2><div class="status-tags"><el-tag>{{statusText(detail.status)}}</el-tag><el-tag v-if="detail.printedAt" type="primary">已打印 {{detail.printCount}} 次</el-tag></div></div>
            <div class="document-number">
              <div class="number-cell"><b>日期(D)</b><el-date-picker v-if="detail.status==='DRAFT'" v-model="headerForm.dispatchDate" type="date" value-format="YYYY-MM-DD" :clearable="false" @change="markDraftDirty"/><span v-else>{{detail.dispatchDate}}</span></div>
              <div class="number-cell"><b>单据编号(N)</b><span>{{detail.dispatchNo}}</span></div>
            </div>
          </div>
          <div class="legacy-header-grid">
            <label><span>路线(A)</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.routeId" filterable clearable placeholder="可留空" @change="markDraftDirty"><el-option v-for="item in routes" :key="item.id" :label="`${item.code} ${item.name}`" :value="item.id"/></el-select><em v-else>{{detail.routeName||'—'}}</em></label>
            <label><span>车辆</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.vehicleId" filterable clearable placeholder="可留空" @change="markDraftDirty"><el-option v-for="item in vehicles" :key="item.id" :label="vehicleLabel(item)" :value="item.id"/></el-select><em v-else>{{detail.vehicleCode||'—'}}</em></label>
            <label><span>司机</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.driverId" filterable clearable placeholder="可留空" @change="markDraftDirty"><el-option v-for="item in drivers" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select><em v-else>{{detail.driverName||'—'}}</em></label>
            <label><span>送货人</span><el-select v-if="detail.status==='DRAFT'" v-model="headerForm.deliveryPersonId" filterable clearable placeholder="可留空" @change="markDraftDirty"><el-option v-for="item in employees" :key="item.id" :label="employeeLabel(item)" :value="item.id"/></el-select><em v-else>{{detail.deliveryPersonName||'—'}}</em></label>
          </div>
          <div v-if="detail.status==='DRAFT'" class="order-entry-row"><label><span>送货单</span><el-input ref="orderTailInput" v-model="orderTail" clearable autofocus placeholder="输入销售单尾号；留空查询全部" @keyup.enter="resolveOrderTail"/></label><el-button type="primary" :loading="orderSearching||resolving" @click="resolveOrderTail">查找</el-button><small>尾号唯一自动加入；多个匹配时在下方选择。仅显示已打印、未加入其他出车表的销售单。</small></div>
          <div v-if="detail.status==='DRAFT' && availableOrders.length" class="candidate-sheet"><div class="candidate-title">查找结果（{{availableOrders.length}}）</div><el-table :data="availableOrders" v-loading="orderSearching" border max-height="220" size="small"><el-table-column prop="orderNo" label="销售单号" width="150"/><el-table-column prop="orderDate" label="日期" width="110"/><el-table-column prop="customerCode" label="客户编号" width="105"/><el-table-column prop="customerName" label="客户名称" min-width="190"/><el-table-column prop="salespersonName" label="业务员" width="95"/><el-table-column prop="totalAmount" label="金额" width="110"/><el-table-column label="操作" width="72" fixed="right"><template #default="scope"><el-button link type="primary" :loading="resolving" @click="addResolvedOrder(scope.row.orderNo)">加入</el-button></template></el-table-column></el-table></div>
          <div v-if="detail.status!=='DRAFT'" class="locked-notice">{{detail.status==='APPROVED'?'该出车表已经审核，内容不可修改':'该出车表已作废'}}</div>
          <el-table :data="detail.orders" border highlight-current-row size="small" class="document-lines" @row-dblclick="openSalesDetail"><el-table-column prop="sequenceNo" label="序号" width="58"/><el-table-column label="单据类型" width="82"><template #default>送货单</template></el-table-column><el-table-column prop="orderDate" label="开单日期" width="106"/><el-table-column label="销售单号" width="145"><template #default="scope"><el-button link type="primary" @click="openSalesDetail(scope.row)">{{scope.row.orderNo}}</el-button></template></el-table-column><el-table-column prop="customerCode" label="客户编号" width="100"/><el-table-column prop="customerName" label="客户名称" min-width="190"/><el-table-column prop="salespersonName" label="业务员" width="92"/><el-table-column prop="settlementMethod" label="结算方式" width="92"/><el-table-column prop="amount" label="金额" width="105"/><el-table-column v-if="detail.status==='DRAFT'" label="操作" width="68"><template #default="scope"><el-button link type="danger" @click="removeOrder(scope.row)">删除</el-button></template></el-table-column></el-table>
          <div class="dispatch-summary"><strong>合计</strong><span>送货单金额：<b>¥{{totalAmount.toFixed(2)}}</b></span><span>欠单金额：<b>¥0.00</b></span><span>总行数：<b>{{detail.orders.length}}</b></span><span>总金额：<b>¥{{totalAmount.toFixed(2)}}</b></span></div>
          <div class="document-footer"><label class="remark-line"><span>备注(R)</span><el-input v-if="detail.status==='DRAFT'" v-model="headerForm.remark" @input="markDraftDirty"/><em v-else>{{detail.remark||'无'}}</em></label><div class="operator-grid"><span>录入人：<b>{{detail.createdByName||'—'}}</b></span><span>录入时间：<b>{{formatDateTime(detail.createdAt)}}</b></span><span>修改人：<b>{{detail.updatedByName||'—'}}</b></span><span>修改时间：<b>{{formatDateTime(detail.updatedAt)}}</b></span><span>审核人：<b>{{detail.approvedByName||'—'}}</b></span><span>审核时间：<b>{{formatDateTime(detail.approvedAt)}}</b></span><span>打印人：<b>{{detail.printedByName||'—'}}</b></span><span>打印时间：<b>{{formatDateTime(detail.printedAt)}}</b></span></div></div>
        </div>
      </template>
    </el-dialog>


    <el-dialog v-model="salesDetailDialog" :title="`相关单据 ${salesDetail?.orderNo||''}`" width="960px" append-to-body class="sales-detail-dialog">
      <div v-loading="salesDetailLoading" class="sales-print-host"><SalesOrderPrint v-if="salesDetail" :detail="salesDetail" type="delivery"/></div>
      <template #footer><el-button @click="salesDetailDialog=false">关闭</el-button><el-button type="primary" :disabled="!salesDetail" @click="printRelated">送货单打印预览</el-button></template>
    </el-dialog>

    <el-dialog v-model="dispatchPrintDialog" :title="`出车表打印预览 ${detail?.dispatchNo||''}`" width="1000px" append-to-body class="dispatch-print-dialog">
      <div v-if="detail" class="dispatch-print-area"><div class="delivery-print-title">出车表</div><div class="dispatch-print-meta"><span><strong>单号：</strong>{{detail.dispatchNo}}</span><span><strong>日期：</strong>{{detail.dispatchDate}}</span><span><strong>路线：</strong>{{detail.routeName}}</span><span><strong>车辆：</strong>{{detail.vehicleCode}}</span><span><strong>司机：</strong>{{detail.driverName}}</span><span><strong>送货人：</strong>{{detail.deliveryPersonName||'—'}}</span><span><strong>打印状态：</strong>{{detail.printedAt?`已打印 ${detail.printCount} 次`:'未打印'}}</span></div>
        <el-table :data="detail.orders" border><el-table-column prop="sequenceNo" label="序号" width="65"/><el-table-column prop="orderNo" label="销售单号" width="145"/><el-table-column prop="orderDate" label="开单日期" width="105"/><el-table-column prop="customerCode" label="客户编号" width="110"/><el-table-column prop="customerName" label="客户名称" min-width="190"/><el-table-column prop="salespersonName" label="业务员" width="90"/><el-table-column prop="settlementMethod" label="结算方式" width="90"/><el-table-column prop="amount" label="金额" width="105"/></el-table>
        <div class="delivery-print-total">合计：{{detail.orders.length}} 张，¥{{totalAmount.toFixed(2)}}</div><div class="delivery-print-footer"><span>备注：{{detail.remark||'无'}}</span><span>制表人：系统管理员</span></div></div>
      <template #footer><el-button @click="dispatchPrintDialog=false">关闭</el-button><el-button @click="exportDispatch">导出 CSV</el-button><el-button type="primary" @click="printDispatchSheet">打印 / 另存 PDF</el-button></template>
    </el-dialog>
  </section>
</template>
